/**
 * 字符显示宽度。局部 VT 解析器要靠它推进光标列号。
 *
 * 不追求 Unicode 全表精确 —— 目标是覆盖内层 coding CLI 实际会输出的东西：
 * ASCII、框线字符、CJK、emoji、组合记号（zero-width）。
 * 宽度算错的后果是光标还原偏一列，不是崩溃。
 */
/** 组合记号 / 变体选择符 / 零宽字符 —— 宽度 0。 */
const ZERO_WIDTH = [
    [0x0300, 0x036f], // 组合变音符
    [0x0483, 0x0489],
    [0x0591, 0x05bd],
    [0x0610, 0x061a],
    [0x064b, 0x065f],
    [0x0670, 0x0670],
    [0x06d6, 0x06dc],
    [0x0900, 0x0903],
    [0x093a, 0x093a],
    [0x093c, 0x093c],
    [0x0941, 0x0948],
    [0x200b, 0x200f], // 零宽空格 / 方向标记
    [0x202a, 0x202e],
    [0x2060, 0x2064],
    [0x20d0, 0x20f0], // 组合符号记号
    [0xfe00, 0xfe0f], // 变体选择符（含 emoji VS16）
    [0xfe20, 0xfe2f],
    [0xfeff, 0xfeff], // BOM
    [0x1ab0, 0x1aff],
    [0x1dc0, 0x1dff],
    [0xe0100, 0xe01ef], // 变体选择符补充
];
/** 双宽（fullwidth / wide）—— 宽度 2。 */
const WIDE = [
    [0x1100, 0x115f], // 韩文字母 Jamo
    [0x231a, 0x231b], // ⌚⌛
    [0x2329, 0x232a],
    [0x23e9, 0x23ec],
    [0x23f0, 0x23f0],
    [0x23f3, 0x23f3],
    [0x25fd, 0x25fe],
    [0x2614, 0x2615],
    [0x2648, 0x2653],
    [0x267f, 0x267f],
    [0x2693, 0x2693],
    [0x26a1, 0x26a1],
    [0x26aa, 0x26ab],
    [0x26bd, 0x26be],
    [0x26c4, 0x26c5],
    [0x26ce, 0x26ce],
    [0x26d4, 0x26d4],
    [0x26ea, 0x26ea],
    [0x26f2, 0x26f3],
    [0x26f5, 0x26f5],
    [0x26fa, 0x26fa],
    [0x26fd, 0x26fd],
    [0x2705, 0x2705],
    [0x270a, 0x270b],
    [0x2728, 0x2728],
    [0x274c, 0x274c],
    [0x274e, 0x274e],
    [0x2753, 0x2755],
    [0x2757, 0x2757],
    [0x2795, 0x2797],
    [0x27b0, 0x27b0],
    [0x27bf, 0x27bf],
    [0x2b1b, 0x2b1c],
    [0x2b50, 0x2b50],
    [0x2b55, 0x2b55],
    [0x2e80, 0x303e], // CJK 部首 / 假名标点
    [0x3041, 0x33ff], // 平假名 片假名 注音 CJK兼容
    [0x3400, 0x4dbf], // CJK 扩展A
    [0x4e00, 0x9fff], // CJK 基本区
    [0xa000, 0xa4cf], // 彝文
    [0xa960, 0xa97f],
    [0xac00, 0xd7a3], // 韩文音节
    [0xf900, 0xfaff], // CJK 兼容表意
    [0xfe10, 0xfe19],
    [0xfe30, 0xfe6f], // CJK 兼容形式
    [0xff00, 0xff60], // 全角 ASCII
    [0xffe0, 0xffe6], // 全角符号
    [0x16fe0, 0x16fe4],
    [0x17000, 0x18cd5],
    [0x1b000, 0x1b2fb],
    [0x1f004, 0x1f004], // 🀄
    [0x1f0cf, 0x1f0cf],
    [0x1f18e, 0x1f18e],
    [0x1f191, 0x1f19a],
    [0x1f200, 0x1f320],
    [0x1f32d, 0x1f335],
    [0x1f337, 0x1f37c],
    [0x1f37e, 0x1f393],
    [0x1f3a0, 0x1f3ca],
    [0x1f3cf, 0x1f3d3],
    [0x1f3e0, 0x1f3f0],
    [0x1f3f4, 0x1f3f4],
    [0x1f3f8, 0x1f43e],
    [0x1f440, 0x1f440],
    [0x1f442, 0x1f4fc],
    [0x1f4ff, 0x1f53d],
    [0x1f54b, 0x1f54e],
    [0x1f550, 0x1f567],
    [0x1f57a, 0x1f57a],
    [0x1f595, 0x1f596],
    [0x1f5a4, 0x1f5a4],
    [0x1f5fb, 0x1f64f],
    [0x1f680, 0x1f6c5],
    [0x1f6cc, 0x1f6cc],
    [0x1f6d0, 0x1f6d2],
    [0x1f6d5, 0x1f6d7],
    [0x1f6eb, 0x1f6ec],
    [0x1f6f4, 0x1f6fc],
    [0x1f7e0, 0x1f7eb],
    [0x1f90c, 0x1f93a],
    [0x1f93c, 0x1f945],
    [0x1f947, 0x1f9ff],
    [0x1fa70, 0x1faf6],
    [0x20000, 0x3fffd], // CJK 扩展B+
];
function inRanges(cp, ranges) {
    let lo = 0;
    let hi = ranges.length - 1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        const r = ranges[mid];
        if (cp < r[0])
            hi = mid - 1;
        else if (cp > r[1])
            lo = mid + 1;
        else
            return true;
    }
    return false;
}
/**
 * 单个码位的显示宽度。
 * 控制字符返回 0（调用方在进入这里之前就该把它们当控制字符处理掉）。
 */
export function charWidth(cp) {
    if (cp === 0)
        return 0;
    if (cp < 32 || (cp >= 0x7f && cp < 0xa0))
        return 0;
    if (cp < 0x0300)
        return 1; // 快路径：拉丁 / 常见符号
    if (inRanges(cp, ZERO_WIDTH))
        return 0;
    if (inRanges(cp, WIDE))
        return 2;
    return 1;
}
/** 字符串的显示宽度（按码位遍历，正确处理代理对）。 */
export function stringWidth(s) {
    let w = 0;
    for (const ch of s)
        w += charWidth(ch.codePointAt(0));
    return w;
}
